def caesar(s, k):
    out = []
    for c in s:
        if c.islower():
            out.append(chr((ord(c) - ord('a') + k) % 26 + ord('a')))
        elif c.isupper():
            out.append(chr((ord(c) - ord('A') + k) % 26 + ord('A')))
        else:
            out.append(c)
    return ''.join(out)
```

