def roman_to_int(s: str) -> int:
    values = {
        'I': 1,
        'V': 5,
        'X': 10,
        'L': 50,
        'C': 100,
        'D': 500,
        'M': 1000,
    }
    total = 0
    for i, char in enumerate(s):
        if i < len(s) - 1 and values[char] < values[s[i + 1]]:
            total -= values[char]
        else:
            total += values[char]
    return total
```

