def merge_intervals(iv):
    if not iv:
        return []
    iv.sort(key=lambda x: x[0])
    result = [iv[0]]
    for s, e in iv[1:]:
        if s <= result[-1][1]:
            result[-1][1] = max(result[-1][1], e)
        else:
            result.append([s, e])
    return result
```

